function runnerUpDigit(s: string): number {
  const seen = new Array(10).fill(false);
  for (const ch of s) if (ch >= "0" && ch <= "9") seen[ch.charCodeAt(0) - 48] = true;
  let found = 0;
  for (let d = 9; d >= 0; d--) {
    if (seen[d] && ++found === 2) return d;
  }
  return -1;
}

